const onboarding = $('Search Onboarding').all();
const activity = $('Search Activity Log').all();

const now = Date.now();

const records = onboarding.map(item => {
  const f = item.json.fields || item.json;
  const clientName = f['Client Name'] || '';
  const status = f['Status'] || '';
  const lastStatusChange = f['Last Status Change'];
  const recordId = item.json.id || f.id;

  let hoursElapsed = 0;
  if (lastStatusChange) {
    hoursElapsed = (now - new Date(lastStatusChange).getTime()) / (1000 * 60 * 60);
  }

  let nudgeThreshold;
  let escalationThreshold;

  switch (status) {
    case 'Intake Received':
      nudgeThreshold = 24;
      escalationThreshold = 48;
      break;
    case 'Contract Sent':
      nudgeThreshold = 48;
      escalationThreshold = 120;
      break;
    case 'Deposit Awaiting Payment':
      nudgeThreshold = 48;
      escalationThreshold = 96;
      break;
    case 'Final Payment Awaiting Payment':
      nudgeThreshold = 48;
      escalationThreshold = 96;
      break;
    default:
      return null;
  }

  const alreadyNudged = activity.some(logItem => {
    const log = logItem.json.fields || logItem.json;
    const event = String(log['Event'] || '');
    const note = String(log['Note'] || '');

    return event.includes('Nudge Sent') &&
      event.includes(status) &&
      note.includes(clientName);
  });

  let action = 'none';

  if (hoursElapsed >= escalationThreshold) {
    action = 'escalate';
  } else if (hoursElapsed >= nudgeThreshold && !alreadyNudged) {
    action = 'nudge';
  }

  return {
    json: {
      ...f,
      id: recordId,
      hoursElapsed: Math.round(hoursElapsed * 100) / 100,
      action,
      alreadyNudged,
      nudgeThreshold,
      escalationThreshold
    }
  };
}).filter(Boolean);

return records;
